tools.example:
reg = Disk[];
sol = NDSolveValue[{-Laplacian[u[x, y], {x, y}] == 1,
   DirichletCondition[u[x, y] == 0, True]}, u, {x, y} \[Element] reg];
Plot3D[sol[x, y], {x, y} \[Element] reg]

reg = Rectangle[{0, 0}, {2, 1}];
u = NDSolveValue[{-Laplacian[u[x, y], {x, y}] == 0,
   DirichletCondition[u[x, y] == 100, x == 0],
   DirichletCondition[u[x, y] == 0, x == 2]}, u, {x, y} \[Element] reg];
ContourPlot[u[x, y], {x, y} \[Element] reg]

reg = Rectangle[{0, 0}, {2, 1}];
u = NDSolveValue[{-Laplacian[u[x, y], {x, y}] == NeumannValue[5, x == 2],
   DirichletCondition[u[x, y] == 0, x == 0]}, u, {x, y} \[Element] reg];
DensityPlot[u[x, y], {x, y} \[Element] reg]

reg = Rectangle[{0, 0}, {1, 1}];
u = NDSolveValue[{-Laplacian[u[x, y], {x, y}] == Sin[2 Pi y],
   PeriodicBoundaryCondition[u[x, y], x == 1, TranslationTransform[{-1, 0}]],
   DirichletCondition[u[x, y] == 0, y == 0 || y == 1]},
  u, {x, y} \[Element] reg];
ContourPlot[u[x, y], {x, y} \[Element] reg]

Needs["NDSolve`FEM`"];
mesh = ToElementMesh[Disk[], "MaxCellMeasure" -> 0.01, "MeshOrder" -> 2];
mesh["Wireframe"]

Needs["NDSolve`FEM`"];
bmesh = ToBoundaryMesh[Disk[], "MaxCellMeasure" -> 0.05];
mesh = ToElementMesh[bmesh];
mesh["Wireframe"]

Needs["NDSolve`FEM`"];
mesh = ToElementMesh[Rectangle[{0, 0}, {2, 1}], "MaxCellMeasure" -> 0.02];
{Length[mesh["Coordinates"]], mesh["Wireframe"]}

Needs["NDSolve`FEM`"];
mesh = ToElementMesh[Disk[], "MaxCellMeasure" -> 0.02];
vals = (#[[1]]^2 + #[[2]]^2) & /@ mesh["Coordinates"];
f = ElementMeshInterpolation[{mesh}, vals];
f[0.3, 0.4]

pars = <|"MassDensity" -> 1, "SpecificHeatCapacity" -> 1,
   "ThermalConductivity" -> 1|>;
pde = HeatTransferPDEComponent[{T[t, x, y], t, {x, y}}, pars] == 0;
sol = NDSolveValue[{pde, DirichletCondition[T[t, x, y] == 100, x == 0],
   T[0, x, y] == 0}, T, {t, 0, 1}, {x, y} \[Element] Rectangle[{0, 0}, {1, 1}]];
Plot3D[sol[1, x, y], {x, 0, 1}, {y, 0, 1}]

pars = <|"RelativePermittivity" -> 1|>;
pde = ElectrostaticPDEComponent[{V[x, y], {x, y}}, pars] == 0;
V = NDSolveValue[{pde, DirichletCondition[V[x, y] == 1, x^2 + y^2 <= 0.11],
   DirichletCondition[V[x, y] == 0, x^2 + y^2 >= 3.9]}, V,
  {x, y} \[Element] RegionDifference[Disk[{0, 0}, 2], Disk[{0, 0}, 0.3]]];
ContourPlot[V[x, y], {x, -2, 2}, {y, -2, 2}]

pars = <|"ReducedPlanckConstant" -> 1, "Mass" -> 1,
   "ElectricPotential" -> (x^2 + y^2)/2|>;
op = SchrodingerPDEComponent[{psi[x, y], {x, y}}, pars];
NDEigenvalues[{op, DirichletCondition[psi[x, y] == 0, True]}, psi,
 {x, y} \[Element] Disk[{0, 0}, 6], 4]

pde = LaplacianPDETerm[{u[x, y], {x, y}}] == 1;
NDSolveValue[{pde, DirichletCondition[u[x, y] == 0, True]}, u,
 {x, y} \[Element] Disk[]]

pde = LaplacianPDETerm[{u[x, y], {x, y}}] +
   SourcePDETerm[{u[x, y], {x, y}}, Sin[x] Sin[y]] == 0;
Head[pde]
